import numpy as np
from scipy.optimize import minimize

def solve_max_sum(n):
    # Objective: sum a_i * a_{i+2}
    # Constraints: a_i + a_{i+1} + a_{i+2} <= 2, a_i >= 0
    def objective(a):
        s = 0
        for i in range(n):
            s += a[i] * a[(i + 2) % n]
        return -s

    cons = []
    for i in range(n):
        def constraint(a, i=i):
            return 2 - (a[i] + a[(i + 1) % n] + a[(i + 2) % n])
        cons.append({'type': 'ineq', 'fun': constraint})

    bounds = [(0, 2) for _ in range(n)]

    # Try several starting points
    best_s = 0
    for start in [np.ones(n) * (2/3), np.ones(n) * 1.0, np.zeros(n), np.ones(n) * 0.5]:
        res = minimize(objective, start, bounds=bounds, constraints=cons, method='SLSQP')
        if res.success:
            best_s = max(best_s, -res.fun)
    return best_s

for n in [4, 6, 8, 10, 12]:
    print(f"n={n}: {solve_max_sum(n)}")

